package controller

import("errors";"net/http";"github.com/gin-gonic/gin";"github.com/google/uuid";"github.com/onoja217/users-management-app/internal/audit";"github.com/onoja217/users-management-app/internal/httpx";"github.com/onoja217/users-management-app/internal/models";"github.com/onoja217/users-management-app/internal/middleware";"github.com/onoja217/users-management-app/internal/service")
type AssessmentResultController struct{service *service.AssessmentResultService}

func (ctrl *AssessmentResultController) requestService(c *gin.Context) (*service.AssessmentResultService, bool) { tx, ok := middleware.TenantDBFromContext(c); if !ok || tx == nil { httpx.Error(c, 500, "tenant_transaction_required", "tenant transaction is required"); return nil, false }; return ctrl.service.WithDB(tx), true }
func NewAssessmentResultController(s *service.AssessmentResultService)*AssessmentResultController{return &AssessmentResultController{service:s}}
type assessmentResultRequest struct{AssessmentID uuid.UUID `json:"assessment_id"`;StudentEnrollmentID uuid.UUID `json:"student_enrollment_id"`;Score float64 `json:"score"`}
func assessmentResultError(c *gin.Context,e error){switch{case errors.Is(e,service.ErrResultNotFound):httpx.Error(c,404,"result_not_found","assessment result not found");case errors.Is(e,service.ErrResultAssessmentMissing):httpx.Error(c,404,"assessment_not_found","assessment not found");case errors.Is(e,service.ErrResultEnrollmentMissing):httpx.Error(c,404,"enrollment_not_found","student enrollment not found");case errors.Is(e,service.ErrResultDuplicate):httpx.Error(c,409,"result_duplicate","result already exists");case errors.Is(e,service.ErrResultInvalid):httpx.Error(c,400,"invalid_result","invalid assessment result");default:httpx.Error(c,500,"result_operation_failed","assessment result operation failed")}}
func(ctrl *AssessmentResultController)List(c *gin.Context){svc,ok:=ctrl.requestService(c);if !ok{return};schoolID,ok:=requireSchoolID(c);if !ok{return};sessionID,termID,ok:=parseAcademicQuery(c);if !ok{return};v,e:=svc.List(schoolID,sessionID,termID);if e!=nil{assessmentResultError(c,e);return};c.JSON(http.StatusOK,v)}
func(ctrl *AssessmentResultController)Get(c *gin.Context){svc,ok:=ctrl.requestService(c);if !ok{return};schoolID,ok:=requireSchoolID(c);if !ok{return};id,e:=uuid.Parse(c.Param("id"));if e!=nil{httpx.Error(c,400,"invalid_result_id","invalid result id");return};v,e:=svc.Get(schoolID,id);if e!=nil{assessmentResultError(c,e);return};c.JSON(http.StatusOK,v)}
func(ctrl *AssessmentResultController)Create(c *gin.Context){svc,ok:=ctrl.requestService(c);if !ok{return};schoolID,ok:=requireSchoolID(c);if !ok{return};var r assessmentResultRequest;if e:=c.ShouldBindJSON(&r);e!=nil||r.AssessmentID==uuid.Nil||r.StudentEnrollmentID==uuid.Nil||r.Score<0{httpx.Error(c,400,"invalid_result_request","assessment, enrollment and non-negative score are required");return};v,e:=svc.Create(schoolID,models.AssessmentResult{AssessmentID:r.AssessmentID,StudentEnrollmentID:r.StudentEnrollmentID,Score:r.Score});if e!=nil{assessmentResultError(c,e);return};actor,_:=uuid.Parse(c.GetString("user_id"));_=audit.Record(svc.DB(),c,&actor,"assessment_result.create","assessment_result",&v.ID,nil);c.JSON(http.StatusCreated,v)}
func(ctrl *AssessmentResultController)Update(c *gin.Context){svc,ok:=ctrl.requestService(c);if !ok{return};schoolID,ok:=requireSchoolID(c);if !ok{return};id,e:=uuid.Parse(c.Param("id"));if e!=nil{httpx.Error(c,400,"invalid_result_id","invalid result id");return};var r assessmentResultRequest;if e=c.ShouldBindJSON(&r);e!=nil||r.AssessmentID==uuid.Nil||r.StudentEnrollmentID==uuid.Nil||r.Score<0{httpx.Error(c,400,"invalid_result_request","assessment, enrollment and non-negative score are required");return};v,e:=svc.Get(schoolID,id);if e!=nil{assessmentResultError(c,e);return};v.AssessmentID=r.AssessmentID;v.StudentEnrollmentID=r.StudentEnrollmentID;v.Score=r.Score;if e=svc.Update(schoolID,v);e!=nil{assessmentResultError(c,e);return};actor,_:=uuid.Parse(c.GetString("user_id"));_=audit.Record(svc.DB(),c,&actor,"assessment_result.update","assessment_result",&v.ID,nil);c.JSON(http.StatusOK,v)}
func(ctrl *AssessmentResultController)Delete(c *gin.Context){svc,ok:=ctrl.requestService(c);if !ok{return};schoolID,ok:=requireSchoolID(c);if !ok{return};id,e:=uuid.Parse(c.Param("id"));if e!=nil{httpx.Error(c,400,"invalid_result_id","invalid result id");return};if e=svc.Delete(schoolID,id);e!=nil{assessmentResultError(c,e);return};actor,_:=uuid.Parse(c.GetString("user_id"));_=audit.Record(svc.DB(),c,&actor,"assessment_result.delete","assessment_result",&id,nil);c.JSON(http.StatusOK,gin.H{"message":"assessment result deleted"})}
func(ctrl *AssessmentResultController)ReportCard(c *gin.Context){svc,ok:=ctrl.requestService(c);if !ok{return};schoolID,ok:=requireSchoolID(c);if !ok{return};enrollmentID,e:=uuid.Parse(c.Param("enrollmentId"));if e!=nil{httpx.Error(c,400,"invalid_enrollment_id","invalid enrollment id");return};sessionID,e:=uuid.Parse(c.Query("academic_session_id"));if e!=nil||sessionID==uuid.Nil{httpx.Error(c,400,"invalid_session_id","academic_session_id is required");return};termID,e:=uuid.Parse(c.Query("term_id"));if e!=nil{httpx.Error(c,400,"invalid_term_id","term_id is required");return};v,e:=svc.ReportCardForSchool(schoolID,enrollmentID,sessionID,termID);if e!=nil{assessmentResultError(c,e);return};c.JSON(http.StatusOK,v)}

func(ctrl *AssessmentResultController) TeacherList(c *gin.Context){svc,ok:=ctrl.requestService(c);if !ok{return};schoolID,ok:=requireSchoolID(c);if !ok{return};tid,e:=uuid.Parse(c.GetString("user_id"));if e!=nil{httpx.Error(c,401,"invalid_user","invalid authenticated user");return};sessionID,termID,ok:=parseAcademicQuery(c);if !ok{return};v,e:=svc.ListForTeacher(schoolID,tid,sessionID,termID);if e!=nil{assessmentResultError(c,e);return};c.JSON(http.StatusOK,v)}
func(ctrl *AssessmentResultController) TeacherCreate(c *gin.Context){svc,ok:=ctrl.requestService(c);if !ok{return};schoolID,ok:=requireSchoolID(c);if !ok{return};tid,e:=uuid.Parse(c.GetString("user_id"));if e!=nil{httpx.Error(c,401,"invalid_user","invalid authenticated user");return};var r assessmentResultRequest;if e=c.ShouldBindJSON(&r);e!=nil||r.AssessmentID==uuid.Nil||r.StudentEnrollmentID==uuid.Nil||r.Score<0{httpx.Error(c,400,"invalid_result_request","assessment, enrollment and non-negative score are required");return};v,e:=svc.TeacherCreate(schoolID,tid,models.AssessmentResult{AssessmentID:r.AssessmentID,StudentEnrollmentID:r.StudentEnrollmentID,Score:r.Score});if e!=nil{assessmentResultError(c,e);return};c.JSON(http.StatusCreated,v)}
